// 1. Validate incoming binary payload
const item = $input.first();
const binary = item.binary || {};

// Support both 'data0' and 'file' field names, ensuring consistency to data0
let binaryKey = null;
if (binary.data0) {
  binaryKey = 'data0';
} else if (binary.file) {
  binaryKey = 'file';
  binary.data0 = binary.file;
} else {
  const firstKey = Object.keys(binary)[0];
  if (firstKey) {
    binaryKey = firstKey;
    binary.data0 = binary[firstKey];
  }
}

if (!binaryKey || !binary.data0) {
  return [{
    json: {
      error: true,
      statusCode: 400,
      message: 'No PDF file detected in request. Please send multipart/form-data with binary field data0 or file.'
    }
  }];
}

const mime = binary.data0.mimeType || '';
const fileName = binary.data0.fileName || '';
if (!mime.includes('pdf') && !fileName.toLowerCase().endsWith('.pdf')) {
  return [{
    json: {
      error: true,
      statusCode: 400,
      message: 'Uploaded file is not a valid PDF document.'
    }
  }];
}

return [{
  json: {
    valid: true,
    fileName: fileName,
    userId: item.json.userId || 'demo_user',
    courseId: item.json.courseId || ''
  },
  binary: {
    data0: binary.data0
  }
}];

// Robust JSON sanitizer, validator, and normalizer for MoSPI MCQ standards
const item = $input.first();
let raw = item.json.output || item.json.text || item.json.content || item.json.response || item.json;

if (typeof raw === 'object' && raw.questions && Array.isArray(raw.questions)) {
  return [{ json: normalizeQuestions(raw.questions) }];
}

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

// 1. Strip markdown code fences
raw = raw.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();

// 2. Locate boundaries of JSON
const startIdx = raw.indexOf('{');
const endIdx = raw.lastIndexOf('}');
if (startIdx !== -1 && endIdx !== -1 && endIdx >= startIdx) {
  raw = raw.substring(startIdx, endIdx + 1);
}

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (err) {
  return [{
    json: {
      error: true,
      statusCode: 500,
      message: 'Failed to parse LLM output as JSON: ' + err.message
    }
  }];
}

let questionsArray = [];
if (Array.isArray(parsed)) {
  questionsArray = parsed;
} else if (parsed.questions && Array.isArray(parsed.questions)) {
  questionsArray = parsed.questions;
} else if (parsed.data && Array.isArray(parsed.data.questions)) {
  questionsArray = parsed.data.questions;
} else {
  for (const key of Object.keys(parsed)) {
    if (Array.isArray(parsed[key])) {
      questionsArray = parsed[key];
      break;
    }
  }
}

if (!questionsArray || questionsArray.length === 0) {
  return [{
    json: {
      error: true,
      statusCode: 500,
      message: 'No questions found in LLM JSON output.'
    }
  }];
}

function normalizeQuestions(arr) {
  const normalized = arr.map((q, idx) => {
    const text = q.text || q.question || `Question ${idx + 1}`;
    let rawOpts = q.options || [];
    if (!Array.isArray(rawOpts)) {
      rawOpts = [String(rawOpts)];
    }
    let options = rawOpts.map(o => String(o).trim()).filter(Boolean);
    if (options.length > 4) {
      options = options.slice(0, 4);
    }
    while (options.length < 4) {
      options.push(`Option ${options.length + 1}`);
    }

    let correct = 0;
    if (typeof q.correct === 'number' && q.correct >= 0 && q.correct < options.length) {
      correct = q.correct;
    } else if (typeof q.correctAnswer === 'number' && q.correctAnswer >= 0 && q.correctAnswer < options.length) {
      correct = q.correctAnswer;
    } else if (typeof q.correct === 'string') {
      const c = q.correct.trim();
      if (options.includes(c)) {
        correct = options.indexOf(c);
      } else if (c.length === 1 && 'ABCD'.includes(c.toUpperCase())) {
        correct = c.toUpperCase().charCodeAt(0) - 65;
      }
    }

    return {
      id: q.id || `q_${idx + 1}`,
      text: text,
      type: 'MCQ',
      options: options,
      correct: Math.min(Math.max(correct, 0), options.length - 1),
      explanation: q.explanation || `The correct answer is ${options[correct]}.`,
      competency: q.competency || 'MoSPI Official Statistics',
      topic: q.topic || 'Statistical Methodology'
    };
  });

  return {
    questions: normalized
  };
}

return [{ json: normalizeQuestions(questionsArray) }];
